use std::{fs, path::Path};
fn replace_once(source:&mut String,from:&str,to:&str,label:&str){let count=source.matches(from).count();assert_eq!(count,1,"compact meter patch {label} expected one match, found {count}");*source=source.replacen(from,to,1);}
fn replace_between(source:&mut String,start:&str,end:&str,replacement:&str,label:&str){let sc=source.matches(start).count();assert_eq!(sc,1,"compact meter patch {label} start expected one match, found {sc}");let begin=source.find(start).expect("compact meter start anchor");let finish=source[begin..].find(end).map(|o|begin+o).expect("compact meter end anchor");source.replace_range(begin..finish,replacement);}
pub fn run(out:&Path){let path=out.join("feature_overlays_v170_fixed.rs");let mut source=fs::read_to_string(&path).expect("read generated feature overlay").replace("\r\n","\n");
replace_once(&mut source,r#"unsafe fn dps_row_at(hwnd:HWND,state:&State,y:i32)->Option<DpsRow>{let rc=logical_client_rect(hwnd,state.scale_percent);let scale=dps_layout_scale(state);let row_h=dps_row_h(scale);let top=dps_rows_top();if y<top||y>=rc.bottom{return None;}let screen_i=((y-top)/row_h)as usize;let physical=visible_dps_rows_scaled(rc.bottom,scale);if screen_i>=physical{return None;}meter_page_rows(state,physical).get(screen_i).map(|(_,row)|(*row).clone())}"#,r#"unsafe fn dps_row_at(hwnd:HWND,state:&State,y:i32)->Option<DpsRow>{let rc=logical_client_rect(hwnd,state.scale_percent);let scale=dps_layout_scale(state);let row_h=dps_row_h_for(state,scale);let top=dps_rows_top_for(state);if y<top||y>=rc.bottom{return None;}let screen_i=((y-top)/row_h)as usize;let physical=visible_dps_rows_scaled_for(state,rc.bottom,scale);if screen_i>=physical{return None;}meter_page_rows(state,physical).get(screen_i).map(|(_,row)|(*row).clone())}"#,"row hit compact");
replace_once(&mut source,r#"unsafe fn clamp_scroll(hwnd:HWND,state:&mut State){let rc=logical_client_rect(hwnd,state.scale_percent);let(total,visible)=if state.kind==Kind::Dps{let physical=visible_dps_rows_scaled(rc.bottom,dps_layout_scale(state));(meter_rows(state).len(),meter_regular_page_size(state,physical))}else{let(total,visible,_)=mechanics_scroll_metrics(state,rc.bottom);(total,visible)};state.scroll=state.scroll.min(total.saturating_sub(visible.max(1)));}"#,r#"unsafe fn clamp_scroll(hwnd:HWND,state:&mut State){let rc=logical_client_rect(hwnd,state.scale_percent);let(total,visible)=if state.kind==Kind::Dps{let physical=visible_dps_rows_scaled_for(state,rc.bottom,dps_layout_scale(state));(meter_rows(state).len(),meter_regular_page_size(state,physical))}else{let(total,visible,_)=mechanics_scroll_metrics(state,rc.bottom);(total,visible)};state.scroll=state.scroll.min(total.saturating_sub(visible.max(1)));}"#,"clamp compact");
replace_once(&mut source,r#"let(total,page)=if state.kind==Kind::Dps{let physical=visible_dps_rows_scaled(rc.bottom,dps_layout_scale(state));(meter_rows(state).len(),meter_regular_page_size(state,physical))}else{let(n,p,_)=mechanics_scroll_metrics(state,rc.bottom);(n,p)};"#,r#"let(total,page)=if state.kind==Kind::Dps{let physical=visible_dps_rows_scaled_for(state,rc.bottom,dps_layout_scale(state));(meter_rows(state).len(),meter_regular_page_size(state,physical))}else{let(n,p,_)=mechanics_scroll_metrics(state,rc.bottom);(n,p)};"#,"keyboard compact");
replace_between(&mut source,r#"unsafe fn persist_overlay_rect(state:&mut State,rect:RECT){"#,r#"unsafe fn resize_collapsed_for_scale"#,r#"fn save_meter_view_size(state:&State,rect:RECT){if state.kind!=Kind::Dps{return;}let mut file=read_meter_view(&state.paths);file.compact_mode=state.compact_mode;let slot=meter_view_size_mut(&mut file,state.compact_mode,raid_active(state));slot.width=(rect.right-rect.left).max(1);slot.height=(rect.bottom-rect.top).max(1);slot.scale=state.scale_percent;slot.valid=true;write_meter_view(&state.paths,&file);}
fn save_meter_view_preference(state:&State){if state.kind!=Kind::Dps{return;}let mut file=read_meter_view(&state.paths);file.compact_mode=state.compact_mode;write_meter_view(&state.paths,&file);}
unsafe fn persist_overlay_rect(state:&mut State,rect:RECT){
    if state.kind==Kind::Dps{save_meter_view_size(state,rect);if state.compact_mode{state.expanded=rect;let mut scale_slot=scale_slot(&state.paths,state.kind);let old=scale_slot.percent.max(1);let new=state.scale_percent;if scale_slot.has_bounds&&old!=new{scale_slot.width=rescale_px(scale_slot.width,old,new);scale_slot.height=rescale_px(scale_slot.height,old,new);}scale_slot.percent=new;if new==100{scale_slot.has_bounds=false;}if let Err(err)=save_scale_slot(&state.paths,state.kind,scale_slot){crate::logging::write(format!("overlay scale: compact scale save failed: {err}"));}return;}if raid_active(state){raid_store_rect(state,rect);return;}}
    state.expanded=rect;
    if let Ok(mut features)=state.features.write(){let layout=if state.kind==Kind::Dps{&mut features.dps}else{&mut features.mechanics};layout.x=rect.left;layout.y=rect.top;layout.width=(rect.right-rect.left).max(1);layout.height=(rect.bottom-rect.top).max(1);let snapshot=features.clone();drop(features);if let Err(err)=feature_settings::save(&state.paths,&snapshot){crate::logging::write(format!("feature settings: overlay bounds save failed: {err}"));}}
    let mut slot=scale_slot(&state.paths,state.kind);slot.percent=state.scale_percent;if state.scale_percent==100{slot.has_bounds=false;}else{slot.x=rect.left;slot.y=rect.top;slot.width=(rect.right-rect.left).max(1);slot.height=(rect.bottom-rect.top).max(1);slot.has_bounds=true;}if let Err(err)=save_scale_slot(&state.paths,state.kind,slot){crate::logging::write(format!("overlay scale: bounds save failed: {err}"));}
}
"#,"persist compact");
replace_once(&mut source,r#"let target_w=rescale_px((source.right-source.left).max(1),old,new).max(overlay_min_width(overlay.kind,new));let target_h=rescale_px((source.bottom-source.top).max(1),old,new).max(overlay_min_height(overlay.kind,new));"#,r#"let target_w=rescale_px((source.right-source.left).max(1),old,new).max(overlay_min_width_mode(overlay.kind,new,overlay.compact_mode));let target_h=rescale_px((source.bottom-source.top).max(1),old,new).max(overlay_min_height_mode(overlay.kind,new,overlay.compact_mode));"#,"scale compact minimum");
replace_once(&mut source,r#"unsafe fn expand_state(hwnd:HWND,state:&mut State){let work=crate::ui::work_area(hwnd);let min_w=overlay_min_width(state.kind,state.scale_percent);let min_h=overlay_min_height(state.kind,state.scale_percent);"#,r#"unsafe fn expand_state(hwnd:HWND,state:&mut State){let work=crate::ui::work_area(hwnd);let min_w=overlay_min_width_mode(state.kind,state.scale_percent,state.compact_mode);let min_h=overlay_min_height_mode(state.kind,state.scale_percent,state.compact_mode);"#,"expand compact min");
replace_once(&mut source,r#"unsafe fn save_bounds(hwnd:HWND,state:&mut State){if state.collapsed{return;}let mut rect:RECT=std::mem::zeroed();if GetWindowRect(hwnd,&mut rect)==0{return;}persist_overlay_rect(state,rect);}
"#,r#"unsafe fn save_bounds(hwnd:HWND,state:&mut State){if state.collapsed{return;}let mut rect:RECT=std::mem::zeroed();if GetWindowRect(hwnd,&mut rect)==0{return;}persist_overlay_rect(state,rect);}
unsafe fn toggle_compact_mode(hwnd:HWND,state:&mut State){if state.kind!=Kind::Dps||state.collapsed{return;}let mut current:RECT=std::mem::zeroed();if GetWindowRect(hwnd,&mut current)==0{return;}persist_overlay_rect(state,current);state.compact_mode=!state.compact_mode;save_meter_view_preference(state);let raid=raid_active(state);let file=read_meter_view(&state.paths);let saved=restored_meter_size(meter_view_size(&file,state.compact_mode,raid),state.scale_percent);let size=saved.unwrap_or_else(||if state.compact_mode{default_compact_size(state.scale_percent,raid)}else{let features=state.features.read().map(|f|f.clone()).unwrap_or_default();(scale_px(features.dps.width.max(300),state.scale_percent),scale_px(features.dps.height.max(200),state.scale_percent))});let work=crate::ui::work_area(hwnd);let min_w=overlay_min_width_mode(Kind::Dps,state.scale_percent,state.compact_mode);let min_h=overlay_min_height_mode(Kind::Dps,state.scale_percent,state.compact_mode);let ax=preferred_axis_anchor(current.left,current.right,work.left,work.right);let ay=preferred_axis_anchor(current.top,current.bottom,work.top,work.bottom);let target=anchored_scaled_rect(current,work,size.0.max(min_w),size.1.max(min_h),ax,ay);state.expanded=target;state.scroll=0;SetWindowPos(hwnd,HWND_TOPMOST,target.left,target.top,(target.right-target.left).max(1),(target.bottom-target.top).max(1),SWP_NOACTIVATE);save_meter_view_size(state,target);sync_consumable_popup(hwnd,state);InvalidateRect(hwnd,null(),0);}
"#,"compact toggle");
fs::write(path,source).expect("write compact meter generated overlay");}
